-- Product metadata and simplified field workflow; existing operational records retained.
ALTER TABLE tf_products ADD COLUMN image_url TEXT NOT NULL DEFAULT '';
ALTER TABLE tf_products ADD COLUMN source_url TEXT NOT NULL DEFAULT '';
ALTER TABLE tf_products ADD COLUMN source_id TEXT NOT NULL DEFAULT '';
ALTER TABLE tf_products ADD COLUMN is_bulk INTEGER NOT NULL DEFAULT 0;
ALTER TABLE tf_products ADD COLUMN catalog_at TEXT NOT NULL DEFAULT '';
ALTER TABLE tf_missions ADD COLUMN late_grace_minutes INTEGER NOT NULL DEFAULT 15;
ALTER TABLE tf_missions ADD COLUMN start_photo_id TEXT;
ALTER TABLE tf_missions ADD COLUMN end_photo_id TEXT;
ALTER TABLE tf_photos ADD COLUMN purpose TEXT NOT NULL DEFAULT 'report';
CREATE TABLE IF NOT EXISTS tf_store_prices(store_id TEXT NOT NULL REFERENCES tf_stores(id),product_id TEXT NOT NULL REFERENCES tf_products(id),unit_price INTEGER NOT NULL CHECK(unit_price>0),updated_at TEXT NOT NULL,PRIMARY KEY(store_id,product_id));
CREATE TABLE IF NOT EXISTS tf_alert_ack(user_id TEXT NOT NULL REFERENCES tf_users(id),mission_id TEXT NOT NULL REFERENCES tf_missions(id),kind TEXT NOT NULL CHECK(kind IN ('missing_start','late_start')),ack_at TEXT NOT NULL,PRIMARY KEY(user_id,mission_id,kind));
-- An uncounted product has unknown stock, never zero. Known stocks still prevent overselling.
DROP TRIGGER IF EXISTS tf_ticket_stock;
CREATE TRIGGER tf_ticket_stock BEFORE INSERT ON tf_tickets WHEN NEW.status='valid'
BEGIN
 SELECT RAISE(ABORT,'STOCK_INSUFFICIENT') WHERE EXISTS (
 SELECT 1 FROM json_each(NEW.lines) l JOIN tf_counts s ON s.mission_id=NEW.mission_id AND s.product_id=json_extract(l.value,'$.product_id')
 WHERE s.opening+s.received-s.other_out < json_extract(l.value,'$.qty')+COALESCE((SELECT SUM(json_extract(x.value,'$.qty')) FROM tf_tickets t,json_each(t.lines) x WHERE t.mission_id=NEW.mission_id AND t.status='valid' AND json_extract(x.value,'$.product_id')=s.product_id),0));
END;
